"use client";

/**
 * Film grain: a fine, living grain and a soft vignette laid over whatever sits
 * underneath, so flat UI footage picks up the texture of a photographed frame.
 *
 * Written by Better Design. The grain is browser noise with a seed stepped by
 * frame, so every render of the same frame is identical.
 */
import type { ReactNode } from "react";
import { useId } from "react";
import { AbsoluteFill, random, useCurrentFrame } from "remotion";
import { channels, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

export interface FilmGrainProps {
  /** Drawn under the grain and the vignette. */
  children?: ReactNode;
  /** Grain strength, 0 to 1. 0.1 is subtle, 0.25 is heavy. */
  grain?: number;
  /** Grain size. Higher numbers make finer grain. */
  fineness?: number;
  /** Frames each grain pattern holds. 2 reads as film at 30 fps. */
  holdFrames?: number;
  /** Vignette strength at the corners, 0 to 1. */
  vignette?: number;
  /** Changes the grain pattern while keeping it deterministic. */
  seed?: string;
  theme?: Partial<VideoTheme>;
}

const luminance = (c: string) => {
  const { r, g, b } = channels(c);
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
};

/** Animated grain and a vignette over the page colour, with children underneath. */
export function FilmGrain({ children, grain = 0.12, fineness = 0.85, holdFrames = 2, vignette = 0.5, seed = "grain", theme: themeOverride }: FilmGrainProps) {
  const t = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const id = useId().replace(/[^a-zA-Z0-9-]/g, "");
  const step = Math.floor(frame / Math.max(1, holdFrames));
  const noiseSeed = Math.floor(random(`${seed}-${step}`) * 10000);
  // Shift the tile each step too, so no grain pattern sits still.
  const dx = Math.round(random(`${seed}-x-${step}`) * 200);
  const dy = Math.round(random(`${seed}-y-${step}`) * 200);

  // Grain takes the ink colour: light specks on a dark page, dark on a light one.
  const dark = luminance(t.background) < 0.4;
  const ink = channels(t.foreground);
  // Corners fall toward the ink on a light page and toward black on a dark one.
  const edge = dark ? "oklch(0 0 0 / 1)" : t.foreground;
  const edgeAlpha = dark ? vignette * 0.85 : vignette * 0.22;

  return (
    <AbsoluteFill style={{ background: t.background, overflow: "hidden" }}>
      {children ? <AbsoluteFill>{children}</AbsoluteFill> : null}
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: grain }} aria-hidden>
        <filter id={`grain-${id}`} x="0" y="0" width="100%" height="100%">
          <feTurbulence type="fractalNoise" baseFrequency={fineness} numOctaves={2} seed={noiseSeed} stitchTiles="stitch" />
          <feColorMatrix type="matrix" values={`0 0 0 0 ${ink.r}  0 0 0 0 ${ink.g}  0 0 0 0 ${ink.b}  2.6 0 0 0 -1.05`} />
        </filter>
        <rect x={-dx} y={-dy} width="120%" height="120%" filter={`url(#grain-${id})`} />
      </svg>
      <AbsoluteFill
        style={{ background: `radial-gradient(ellipse 75% 70% at 50% 50%, ${withAlpha(edge, 0)} 45%, ${withAlpha(edge, edgeAlpha * 0.5)} 78%, ${withAlpha(edge, edgeAlpha)} 100%)` }}
      />
    </AbsoluteFill>
  );
}
